def _identifier_key(identifier):
    """Numeric identifiers sort below alphanumeric ones; each kind compares naturally."""
    if identifier.isdigit():
        return (0, int(identifier), "")
    return (1, 0, identifier)


def _precedence_key(version):
    """Return a tuple whose natural ordering matches SemVer 2.0.0 precedence."""
    # Build metadata after '+' is ignored for ordering.
    core = version.split("+", 1)[0]
    core, has_pre, pre = core.partition("-")

    major, minor, patch = (int(part) for part in core.split("."))

    if has_pre:
        # A pre-release sorts below the same version without one (flag 0 < 1).
        # Tuples compare shorter-prefix-first, matching the shorter-list rule.
        pre_key = tuple(_identifier_key(part) for part in pre.split("."))
        return (major, minor, patch, 0, pre_key)
    return (major, minor, patch, 1, ())


def sort_versions(vs):
    """Return the semantic version strings sorted by precedence, lowest first.

    Versions that compare equal keep their input order (sorted is stable).
    """
